public class StudioRenderer(IObjectStore store){
 static readonly SemaphoreSlim RenderGate=new(2,2);
 const double PointsPerMm=72/25.4;
 static SKColor Color(string hex,double opacity=1){var c=SKColor.Parse(hex);return c.WithAlpha((byte)Math.Round(opacity*255));}
 static SKTypeface Font(bool bold){using var input=typeof(StudioRenderer).Assembly.GetManifestResourceStream("Society.Api.Fonts."+(bold?"VeraBd.ttf":"Vera.ttf"))!;return SKTypeface.FromStream(input);}
 public byte[] Image(Guid tenant,CredentialSnapshot snapshot,string side,bool jpeg=false,bool bleed=false,bool preview=false,int dpi=300){RenderGate.Wait();try{var d=snapshot.Design;var pixelsPerMm=dpi/25.4;var margin=bleed?d.BleedMm:0;var width=(int)Math.Ceiling((d.WidthMm+2*margin)*pixelsPerMm);var height=(int)Math.Ceiling((d.HeightMm+2*margin)*pixelsPerMm);if((long)width*height>24000000)throw new DomainException("This physical design exceeds the 24-million-pixel rendering limit; reduce its dimensions");using var surface=SKSurface.Create(new SKImageInfo(width,height))??throw new DomainException("The image renderer could not allocate this document");var canvas=surface.Canvas;canvas.Clear(Color(d.Background));canvas.Scale((float)pixelsPerMm);canvas.Translate((float)margin,(float)margin);foreach(var e in side=="Back"?d.Back:d.Front){canvas.Save();canvas.Translate((float)e.X,(float)e.Y);canvas.RotateDegrees((float)e.Rotation);using var paint=new SKPaint{IsAntialias=true,Color=Color(e.Fill,e.Opacity)};if(e.ShadowBlur>0)paint.ImageFilter=SKImageFilter.CreateDropShadow((float)e.ShadowX,(float)e.ShadowY,(float)e.ShadowBlur,(float)e.ShadowBlur,Color(e.ShadowColor,e.Opacity));var box=SKRect.Create((float)e.Width,(float)e.Height);
  if(e.Type is "Rect" or "Ellipse" or "Line"){if(e.Type=="Rect")canvas.DrawRect(box,paint);if(e.Type=="Ellipse")canvas.DrawOval(box,paint);if(e.Type=="Line"){paint.StrokeWidth=(float)Math.Max(.15,e.StrokeWidth);canvas.DrawLine(0,0,(float)e.Width,(float)e.Height,paint);}if(e.StrokeWidth>0&&e.Type!="Line"){using var stroke=new SKPaint{IsAntialias=true,Color=Color(e.Stroke,e.Opacity),Style=SKPaintStyle.Stroke,StrokeWidth=(float)e.StrokeWidth};if(e.Type=="Rect")canvas.DrawRect(box,stroke);else canvas.DrawOval(box,stroke);}}
  else if(e.Type=="Image"){var id=e.AssetId??(snapshot.Images.TryGetValue(e.Binding,out var image)?image:(Guid?)null);if(id!=null){using var input=store.Open(tenant,id.Value);using var bmp=SKBitmap.Decode(input)??throw new DomainException("Uploaded image cannot be decoded");var source=new SKRect((float)e.CropX*bmp.Width,(float)e.CropY*bmp.Height,(float)(e.CropX+e.CropWidth)*bmp.Width,(float)(e.CropY+e.CropHeight)*bmp.Height);var scale=e.Fit=="cover"?Math.Max(e.Width/source.Width,e.Height/source.Height):Math.Min(e.Width/source.Width,e.Height/source.Height);var w=(float)(source.Width*scale);var h=(float)(source.Height*scale);canvas.ClipRect(box);paint.Color=SKColors.White.WithAlpha((byte)(e.Opacity*255));canvas.DrawBitmap(bmp,source,SKRect.Create(((float)e.Width-w)/2,((float)e.Height-h)/2,w,h),new SKSamplingOptions(SKFilterMode.Linear,SKMipmapMode.Linear),paint);}}
  else if(e.Type=="QR"){using var qr=QRCodeGenerator.GenerateQrCode(snapshot.Fields.GetValueOrDefault("card.qr_code","PREVIEW"),QRCodeGenerator.ECCLevel.M);var size=qr.ModuleMatrix.Count;var step=(float)(Math.Min(e.Width,e.Height)/size);using var qrBackground=new SKPaint{Color=SKColors.White};canvas.DrawRect(box,qrBackground);for(var y=0;y<size;y++)for(var x=0;x<size;x++)if(qr.ModuleMatrix[y][x])canvas.DrawRect(x*step,y*step,step+.01f,step+.01f,paint);}
  else if(e.Type=="Barcode"){var text=DesignSchema.Resolve(e,snapshot.Fields);if(text=="")text=snapshot.Fields.GetValueOrDefault("card.serial_number","");DrawBarcode(canvas,text,e,paint);}
  else{canvas.ClipRect(box);using var face=Font(e.Bold);using var font=new SKFont(face,(float)e.FontSize);var text=DesignSchema.Resolve(e,snapshot.Fields);if(e.Required&&!font.ContainsGlyphs(text.Replace("\r","").Replace("\n","")))throw new DomainException("The embedded font does not support every character in required field "+(e.Binding!=""?e.Binding:e.Id));List<string> Wrap(){var result=new List<string>();foreach(var paragraph in text.Replace("\r","").Split('\n')){var line="";foreach(var word in paragraph.Split(' ')){var candidate=line==""?word:line+" "+word;if(font.MeasureText(candidate)>(float)e.Width&&line!=""){result.Add(line);line=word;}else line=candidate;}result.Add(line);}return result;}var lines=Wrap();while(font.Size>1&&(lines.Count*font.Size*1.25f>e.Height||lines.Any(line=>font.MeasureText(line)>e.Width))){font.Size=Math.Max(1,font.Size-.15f);lines=Wrap();}if(e.Required&&(lines.Count*font.Size*1.25f>e.Height||lines.Any(line=>font.MeasureText(line)>e.Width)))throw new DomainException("Required text does not fit its print box: "+(e.Binding!=""?e.Binding:e.Id));var y=font.Size;foreach(var value in lines){var length=font.MeasureText(value);var x=e.Align=="center"?((float)e.Width-length)/2:e.Align=="right"?(float)e.Width-length:0;canvas.DrawText(value,x,y,SKTextAlign.Left,font,paint);y+=font.Size*1.25f;}}
  canvas.Restore();}
  if(preview){using var face=Font(true);using var font=new SKFont(face,(float)Math.Min(d.WidthMm/7,10));using var ink=new SKPaint{Color=SKColors.Red.WithAlpha(80),IsAntialias=true};canvas.DrawText("DRAFT PREVIEW",3,(float)d.HeightMm-3,SKTextAlign.Left,font,ink);}using var imageOut=surface.Snapshot();using var data=imageOut.Encode(jpeg?SKEncodedImageFormat.Jpeg:SKEncodedImageFormat.Png,jpeg?95:100);return data.ToArray();}finally{RenderGate.Release();}
 }
 // Code 39 uses an explicit restricted alphabet; no dynamic executable barcode content.
 static void DrawBarcode(SKCanvas canvas,string raw,DesignElement e,SKPaint paint){const string alphabet="0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ-. $/+%*";string[] codes=["nnnwwnwnn","wnnwnnnnw","nnwwnnnnw","wnwwnnnnn","nnnwwnnnw","wnnwwnnnn","nnwwwnnnn","nnnwnnwnw","wnnwnnwnn","nnwwnnwnn","wnnnnwnnw","nnwnnwnnw","wnwnnwnnn","nnnnwwnnw","wnnnwwnnn","nnwnwwnnn","nnnnnwwnw","wnnnnwwnn","nnwnnwwnn","nnnnwwwnn","wnnnnnnww","nnwnnnnww","wnwnnnnwn","nnnnwnnww","wnnnwnnwn","nnwnwnnwn","nnnnnnwww","wnnnnnwwn","nnwnnnwwn","nnnnwnwwn","wwnnnnnnw","nwwnnnnnw","wwwnnnnnn","nwnnwnnnw","wwnnwnnnn","nwwnwnnnn","nwnnnnwnw","wwnnnnwnn","nwwnnnwnn","nwnwnwnnn","nwnwnnnwn","nwnnnwnwn","nnnwnwnwn","nwnnwnwnn"];var text="*"+raw.ToUpperInvariant()+"*";if(text.Length>100||text.Any(c=>!alphabet.Contains(c)))throw new DomainException("Code 39 barcode requires uppercase letters, digits or supported punctuation");var total=text.Sum(c=>codes[alphabet.IndexOf(c)].Sum(v=>v=='w'?3:1)+1);var step=(float)e.Width/total;float x=0;foreach(var c in text){var pattern=codes[alphabet.IndexOf(c)];for(var n=0;n<9;n++){var w=(pattern[n]=='w'?3:1)*step;if(n%2==0)canvas.DrawRect(x,0,w,(float)e.Height,paint);x+=w;}x+=step;}}
 public byte[] Pdf(CredentialSnapshot snapshot,byte[] front,byte[]? back,bool bleed=false){using var pdf=new PdfDocument();void Page(byte[] bytes){var p=pdf.AddPage();p.Width=XUnit.FromMillimeter(snapshot.Design.WidthMm+(bleed?snapshot.Design.BleedMm*2:0));p.Height=XUnit.FromMillimeter(snapshot.Design.HeightMm+(bleed?snapshot.Design.BleedMm*2:0));using var g=XGraphics.FromPdfPage(p);using var image=XImage.FromStream(new MemoryStream(bytes));g.DrawImage(image,0,0,p.Width.Point,p.Height.Point);}Page(front);if(back!=null)Page(back);using var output=new MemoryStream();pdf.Save(output,false);return output.ToArray();}
 public byte[] Sheet(IReadOnlyList<(CredentialSnapshot snapshot,byte[] front,byte[]? back)> cards,PrintLayout r){if(cards.Count==0)throw new DomainException("No issued credentials selected");if(r.Columns is <1 or >20||r.Rows is <1 or >30||r.SheetWidthMm is <50 or >1000||r.SheetHeightMm is <50 or >1000||r.MarginMm is <0 or >100||r.GapMm is <0 or >50||Math.Abs(r.OffsetX)>20||Math.Abs(r.OffsetY)>20||r.Sides is not("Front" or "Back" or "Both"))throw new DomainException("Invalid print-sheet layout");if(r.CropMarks&&(r.MarginMm-Math.Max(Math.Abs(r.OffsetX),Math.Abs(r.OffsetY))<1.25||r.GapMm<2.5&&(r.Columns>1||r.Rows>1)))throw new DomainException("Crop marks need at least 1.25 mm clear sheet margin and 2.5 mm card gaps");var d=cards[0].snapshot.Design;if(cards.Any(c=>Math.Abs(c.snapshot.Design.WidthMm-d.WidthMm)>.001||Math.Abs(c.snapshot.Design.HeightMm-d.HeightMm)>.001))throw new DomainException("Print sheets require equal card dimensions");var w=d.WidthMm+(r.Bleed?d.BleedMm*2:0);var h=d.HeightMm+(r.Bleed?d.BleedMm*2:0);if(r.MarginMm+Math.Min(0,r.OffsetX)<0||r.MarginMm+Math.Min(0,r.OffsetY)<0||2*r.MarginMm+r.Columns*w+(r.Columns-1)*r.GapMm+Math.Abs(r.OffsetX)>r.SheetWidthMm||2*r.MarginMm+r.Rows*h+(r.Rows-1)*r.GapMm+Math.Abs(r.OffsetY)>r.SheetHeightMm)throw new DomainException("Cards, gaps and calibration offsets do not fit this physical sheet");using var pdf=new PdfDocument();var per=r.Columns*r.Rows;for(var start=0;start<cards.Count;start+=per){foreach(var side in r.Sides=="Both"?new[]{"Front","Back"}:new[]{r.Sides}){if(side=="Back"&&cards.Skip(start).Take(per).All(c=>c.back==null)){if(r.Sides=="Back")throw new DomainException("Selected credentials have no back design");continue;}var page=pdf.AddPage();page.Width=XUnit.FromMillimeter(r.SheetWidthMm);page.Height=XUnit.FromMillimeter(r.SheetHeightMm);using var g=XGraphics.FromPdfPage(page);for(var i=0;i<per&&start+i<cards.Count;i++){var card=cards[start+i];var column=i%r.Columns;if(side=="Back"&&r.Duplex)column=r.Columns-1-column;var x=r.MarginMm+column*(w+r.GapMm)+(side=="Back"?r.OffsetX:0);var y=r.MarginMm+(i/r.Columns)*(h+r.GapMm)+(side=="Back"?r.OffsetY:0);var bytes=side=="Front"?card.front:card.back;if(bytes==null)continue;using var image=XImage.FromStream(new MemoryStream(bytes));g.DrawImage(image,x*PointsPerMm,y*PointsPerMm,w*PointsPerMm,h*PointsPerMm);if(r.CropMarks){var trim=r.Bleed?d.BleedMm:0;foreach(var corner in new[]{(false,false),(true,false),(false,true),(true,true)}){var pen=new XPen(XColors.Gray,.25);var cx=corner.Item1?x+w-trim:x+trim;var cy=corner.Item2?y+h-trim:y+trim;var outerX=corner.Item1?x+w:x;var outerY=corner.Item2?y+h:y;var dx=corner.Item1?1:-1;var dy=corner.Item2?1:-1;g.DrawLine(pen,(outerX+dx*.25)*PointsPerMm,cy*PointsPerMm,(outerX+dx*1.25)*PointsPerMm,cy*PointsPerMm);g.DrawLine(pen,cx*PointsPerMm,(outerY+dy*.25)*PointsPerMm,cx*PointsPerMm,(outerY+dy*1.25)*PointsPerMm);}}}}}using var output=new MemoryStream();pdf.Save(output,false);return output.ToArray();}
}
